  </section>

  <section class="cln-screen" data-screen="6"><div class="cln-title"><span>6</span><div><h2><i class="ti ti-send"></i> Final Review and Publish</h2><p>Adjust if needed, revalidate changed entries, or publish a completed validation.</p></div></div>
   <div class="card cln-card mb-3"><div class="cln-card-head"><div><h3 id="finalName"><i class="ti ti-calendar-check me-1"></i>Cloned Schedule</h3><p id="finalMeta"></p></div><div class="cln-lifecycle" id="lifecycle"></div></div><div class="card-body"><div id="finalBanner"></div><div class="table-responsive mt-3"><table class="table cln-table"><thead><tr><th>Subject</th><th>Faculty</th><th>Room</th><th>Schedule</th><th>Type</th><th>Status</th></tr></thead><tbody id="finalRows"></tbody></table></div></div></div>
   <div class="cln-actions"><button class="btn btn-outline-secondary" id="reviewDraft"><i class="ti ti-eye me-1"></i>Review Draft</button><a class="btn btn-outline-primary" id="editEntries" href="#"><i class="ti ti-pencil me-1"></i>Edit Entries</a><button class="btn btn-outline-primary" id="saveDraftState"><i class="ti ti-device-floppy me-1"></i>Save Draft</button><button class="btn btn-outline-secondary" id="exportClone"><i class="ti ti-file-export me-1"></i>Export</button><button class="btn btn-outline-secondary" id="printClone"><i class="ti ti-printer me-1"></i>Print</button><button class="btn btn-success ms-auto" id="publishClone"><i class="ti ti-send me-1"></i>Publish Schedule</button></div>
  </section>
 </main>
 <div class="cln-connected"><span class="cln-node"><i class="ti ti-calendar-stats"></i>Previous Schedule</span><i class="ti ti-arrow-right"></i><span class="cln-node active"><i class="ti ti-copy"></i>Cloning Tool</span><i class="ti ti-arrow-right"></i><span class="cln-node"><i class="ti ti-file-pencil"></i>Cloned Draft</span><i class="ti ti-arrow-right"></i><span class="cln-node"><i class="ti ti-shield-search"></i>Conflict Checker</span><i class="ti ti-arrow-right"></i><span class="cln-node"><i class="ti ti-calendar-check"></i>Published Schedule</span></div>
</div>
<div id="clnToast" class="cln-toast d-none"></div><div id="clnOverlay" class="cln-overlay d-none"><div class="cln-dialog"><div class="cln-dialog-head"><div><b><i class="ti ti-history me-1"></i>Cloning History</b><div class="text-muted small">Source lineage, validation, and publication events</div></div><button class="btn-close" id="closeHistory" aria-label="Close"></button></div><div class="p-3" id="historyBody"></div></div></div>

<script>
(()=>{'use strict';
const API='<?= BASE_URL ?>/api/scheduling/clone-schedule.php',CONFLICT='<?= BASE_URL ?>/api/scheduling/conflict-check.php',BASE='<?= BASE_URL ?>';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={data:null,source:null,preview:null,batch:null,run:null,step:1,unlocked:1};
async function request(url,options={}){const r=await fetch(url,options),j=await r.json().catch(()=>null);if(!r.ok||!j?.ok)throw new Error(j?.error||'The request could not be completed.');return j}
function toast(msg,type=''){const t=$('clnToast');t.textContent=msg;t.className='cln-toast '+type;setTimeout(()=>t.classList.add('d-none'),5000)}
function go(n){if(n>S.unlocked)return;S.step=n;document.querySelectorAll('.cln-screen').forEach(x=>x.classList.toggle('active',+x.dataset.screen===n));document.querySelectorAll('.cln-step').forEach(x=>{const v=+x.dataset.step;x.classList.toggle('active',v===n);x.classList.toggle('done',v<n)});window.scrollTo({top:0,behavior:'smooth'})}
function unlock(n){S.unlocked=Math.max(S.unlocked,n);go(n)}
function pill(status){const c=status==='Published'||status==='Ready to Publish'?'p-green':status==='Has Conflicts'?'p-red':status==='Validated'?'p-blue':status==='Draft'?'p-orange':'p-gray';return `<span class="cln-pill ${c}">${esc(status||'Unknown')}</span>`}
function dl(rows){return rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${v}</dd>`).join('')}
function fillSelect(el,values,placeholder){el.innerHTML=(placeholder?`<option value="">${placeholder}</option>`:'')+values.map(v=>`<option value="${esc(typeof v==='object'?v.value:v)}">${esc(typeof v==='object'?v.label:v)}</option>`).join('')}
async function load(){try{const j=await request(API+'?action=dashboard');S.data=j;fillSelect($('sourceAY'),j.filters.academic_years,'All years');fillSelect($('sourceSem'),j.filters.semesters,'All semesters');fillSelect($('sourceProgram'),j.filters.programs,'All programs');fillSelect($('targetAY'),j.filters.academic_years);fillSelect($('targetSem'),j.filters.semesters);fillSelect($('targetProgram'),j.filters.programs,'All programs');renderSources();populateTargets();renderHistory()}catch(e){toast(e.message,'error')}}
function filteredSources(){const q=$('sourceSearch').value.trim().toLowerCase();return S.data.sources.filter(x=>(!$('sourceAY').value||x.academic_year===$('sourceAY').value)&&(!$('sourceSem').value||x.semester===$('sourceSem').value)&&(!$('sourceProgram').value||x.program===$('sourceProgram').value)&&(!q||(`${x.code} ${x.name} ${x.program}`).toLowerCase().includes(q)))}
function renderSources(){const rows=filteredSources();$('sourceCount').textContent=rows.length+' schedule'+(rows.length===1?'':'s');$('sourceRows').innerHTML=rows.length?rows.map(x=>`<tr><td><b>${esc(x.code)} · Regular</b><small class="d-block text-muted">${esc(x.name)}</small></td><td>${esc(x.program)}</td><td>${esc(x.academic_year)}<small class="d-block text-muted">${esc(x.semester)}</small></td><td>${x.entry_count}</td><td>${x.faculty_count}</td><td>${x.room_count}</td><td>${pill(x.status_label)}</td><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary" data-preview-source="${x.section_id}"><i class="ti ti-eye"></i></button> <button class="btn btn-sm btn-primary" data-use-source="${x.section_id}"><i class="ti ti-check me-1"></i>Select</button></td></tr>`).join(''):'<tr><td colspan="8" class="cln-empty"><i class="ti ti-calendar-off"></i><br>No matching source schedules.</td></tr>';$('sourceRows').querySelectorAll('[data-preview-source]').forEach(b=>b.onclick=()=>chooseSource(+b.dataset.previewSource,false));$('sourceRows').querySelectorAll('[data-use-source]').forEach(b=>b.onclick=()=>chooseSource(+b.dataset.useSource,true))}
function chooseSource(id,advance){S.source=S.data.sources.find(x=>x.section_id===id);if(!S.source)return;$('selectedSource').classList.remove('d-none');$('selectedSource').innerHTML=`<i class="ti ti-database-check"></i><div><b>${esc(S.source.code)} · Regular selected</b><small>${esc(S.source.academic_year)} · ${esc(S.source.semester)} · ${S.source.entry_count} entries · ${S.source.subject_count} subjects</small></div>${pill(S.source.status_label)}`;$('toConfigure').disabled=false;populateTargets();if(advance){S.unlocked=Math.max(S.unlocked,2);go(2)}}
function populateTargets(){if(!S.data)return;const ay=$('targetAY').value,sem=$('targetSem').value,program=$('targetProgram').value;const sections=S.data.sections.filter(x=>(!ay||x.academic_year===ay)&&(!sem||x.semester===sem)&&(!program||x.program===program)&&x.id!==S.source?.section_id);fillSelect($('targetSection'),sections.map(x=>({value:x.id,label:`${x.code} — ${x.name}`})),'Select target section…');targetChanged()}
function targetChanged(){const target=S.data?.sections.find(x=>x.id===+$('targetSection').value);if(target&&!$('scheduleName').dataset.edited)$('scheduleName').value=`${target.code} · Regular (Clone)`}
function options(){return{copy_time_slots:$('copyTimes').checked,copy_faculty:$('copyFaculty').checked,copy_rooms:$('copyRooms').checked,copy_class_types:$('copyTypes').checked,auto_conflict_check:$('autoCheck').checked,apply_time_shift:$('applyShift').checked,time_shift_minutes:+$('shiftMinutes').value||0,existing_policy:$('existingPolicy').value,remarks:$('cloneRemarks').value}}
async function generatePreview(){if(!S.source)return toast('Select a source schedule first.','error');const target=+$('targetSection').value;if(!target)return toast('Select a target section.','error');if(!$('scheduleName').value.trim())return toast('Enter a target schedule name.','error');try{const j=await request(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'preview',source_section_id:S.source.section_id,target_section_id:target,options:options()})});S.preview=j.preview;renderPreview();unlock(3)}catch(e){toast(e.message,'error')}}
function renderPreview(){const p=S.preview;$('sourceCompare').innerHTML=dl([['Schedule',esc(p.source.code+' · Regular')],['Academic Year',esc(p.source.academic_year)],['Semester',esc(p.source.semester)],['Program / Section',esc(p.source.program+' / '+p.source.code)],['Status',pill(S.source.status_label)]]);$('targetCompare').innerHTML=dl([['Schedule',esc($('scheduleName').value)],['Academic Year',esc(p.target.academic_year)],['Semester',esc(p.target.semester)],['Program / Section',esc(p.target.program+' / '+p.target.code)],['Initial Status',pill('Draft')]]);const m=p.stats;$('previewMetrics').innerHTML=[['books',m.subjects,'Subjects'],['list-details',m.entries,'Entries'],['users',m.faculty,'Faculty'],['door',m.rooms,'Rooms'],['alert-triangle',m.warnings,'Warnings']].map(x=>`<div class="cln-metric"><i class="ti ti-${x[0]}"></i><b>${x[1]}</b><small>${x[2]}</small></div>`).join('');$('previewRows').innerHTML=p.entries.map(e=>`<tr><td><b>${esc(e.subject_code)}</b><small class="d-block text-muted">${esc(e.subject_name)}</small></td><td>${esc(e.teacher_name||'Not copied')}</td><td>${esc(e.room_code||'Not copied')}</td><td>${esc(e.day_of_week||'Not copied')}<small class="d-block text-muted">${esc(e.time_label)}</small></td><td>${esc(e.time_block_name||'Not linked')}</td><td>${esc(e.class_type)}</td><td>${e.warnings.length?`<span class="cln-pill p-orange">${e.warnings.length} warning(s)</span>`:'<span class="cln-pill p-green"><i class="ti ti-check"></i>Ready</span>'}</td></tr>`).join('');$('previewIssues').innerHTML=p.issues.length?p.issues.map(i=>`<div class="cln-issue ${i.level}"><i class="ti ti-${i.level==='error'?'circle-x':'alert-triangle'}"></i><span>${i.entry?`<b>${esc(i.entry)}:</b> `:''}${esc(i.message)}</span></div>`).join(''):'<div class="cln-issue" style="background:#e8f7f0;color:#08704d"><i class="ti ti-circle-check"></i>No early issues detected. Conflict Checker will still run after cloning.</div>';$('reviewClone').disabled=!p.can_clone}
function renderConfirm(){const p=S.preview;$('cloneSummary').innerHTML=`<dl class="cln-dl">${dl([['Source',esc(`${p.source.code} · ${p.source.academic_year} · ${p.source.semester}`)],['Target',esc(`${p.target.code} · ${p.target.academic_year} · ${p.target.semester}`)],['Schedule Name',esc($('scheduleName').value)],['Entries to Clone',String(p.stats.entries)],['Faculty / Rooms',`${p.stats.faculty} faculty · ${p.stats.rooms} rooms`],['Copy Options',esc([options().copy_time_slots?'Time':'No time',options().copy_faculty?'Faculty':'No faculty',options().copy_rooms?'Rooms':'No rooms',options().copy_class_types?'Class types':'Default type'].join(' · '))],['Result',pill('Draft')]])}</dl>`}
async function createDraft(){const b=$('createDraft');b.disabled=true;try{const j=await request(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'clone',source_section_id:S.source.section_id,target_section_id:+$('targetSection').value,schedule_name:$('scheduleName').value,options:options()})});S.batch=j.batch;renderValidation();unlock(5);toast(j.message,'success');if(j.auto_conflict_check)await runConflict(false)}catch(e){toast(e.message,'error')}finally{b.disabled=false}}
function recordKeys(){return(S.batch?.entries||[]).map(e=>'Regular:'+e.cloned_entry_id)}
async function syncRun(){const j=await request(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'sync_validation',batch_id:S.batch.id,run_id:S.run.run_id})});S.batch=j.batch;return j}
async function runConflict(recheck=false){try{$('validationContent').innerHTML='<div class="cln-validation-empty"><span class="spinner-border text-primary"></span><p class="mt-2 mb-0">Running shared scheduling rules…</p></div>';const body={action:recheck?'recheck':'run',record_keys:recordKeys(),previous_run_id:recheck?(S.run?.run_id||S.batch.latest_validation_run_id||''):'',academic_year:S.batch.target_academic_year,semester:S.batch.target_semester,schedule_type:'Regular'};const j=await request(CONFLICT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});S.run=j.run;const sync=await syncRun();renderValidation();toast(sync.message,+S.run.critical_count?'error':'success')}catch(e){toast(e.message,'error');renderValidation()}}
function renderValidation(){if(!S.batch)return;$('validationBatchMeta').textContent=`${S.batch.reference_no} · ${S.batch.schedule_name} · ${S.batch.cloned_count} Draft entries`;$('validationStatus').outerHTML=pill(S.batch.status).replace('<span','<span id="validationStatus"');const c=$('validationContent');if(!S.run&&S.batch.latest_validation_run_id){loadRun(S.batch.latest_validation_run_id);return}if(!S.run){c.innerHTML='<div class="cln-validation-empty"><i class="ti ti-shield-search"></i><h3 class="h6 mt-2">Draft created—validation required</h3><p class="text-muted">Run Conflict Checker before this clone can proceed.</p><button class="btn btn-primary" id="runCloneCheck"><i class="ti ti-player-play me-1"></i>Run Conflict Check</button></div>';$('runCloneCheck').onclick=()=>runConflict(false);$('recheckClone').disabled=true;$('completeValidation').disabled=true;return}const findings=S.run.findings||[];const critical=+S.run.critical_count;c.innerHTML=`<div class="alert alert-${critical?'danger':'success'}"><i class="ti ti-${critical?'shield-x':'shield-check'} me-1"></i><b>${critical?critical+' critical conflict(s) must be resolved.':'No critical conflicts remain.'}</b> ${S.run.warning_count||0} warning(s) require review.</div><div class="cln-metrics mb-3">${[['list-check',S.run.selected_count,'Checked'],['alert-octagon',critical,'Critical'],['alert-triangle',S.run.warning_count||0,'Warnings'],['circle-check',S.run.status,'Run Status'],['history',S.run.run_id,'Run ID']].map(x=>`<div class="cln-metric"><i class="ti ti-${x[0]}"></i><b style="font-size:${String(x[1]).length>10?'.68rem':'1.15rem'}">${esc(x[1])}</b><small>${x[2]}</small></div>`).join('')}</div><div class="cln-findings">${findings.length?findings.map(f=>{const p=f.affected_records?.primary||{};return`<div class="cln-finding ${f.severity==='Warning'?'warning':''}"><i class="ti ti-${f.severity==='Warning'?'alert-triangle':'alert-octagon'}"></i><div><b>${esc(f.conflict_type)} · ${esc(p.section_code||'')} ${esc(p.subject_code||'')}</b><small><strong>What:</strong> ${esc(f.message)}</small><small><strong>Why:</strong> ${esc(f.explanation)}</small><small><strong>Suggested action:</strong> ${esc(f.recommended_action)}</small></div><a class="btn btn-sm btn-outline-primary" href="${esc(f.module_url||'#')}"><i class="ti ti-tool me-1"></i>Resolve</a></div>`}).join(''):'<div class="cln-success"><i class="ti ti-check"></i><div><b>All conflict checks passed</b><div>No findings were created for this cloned draft.</div></div></div>'}</div>`;$('recheckClone').disabled=false;$('completeValidation').disabled=critical>0||S.run.status==='Completed'}
async function loadRun(id){try{const j=await request(CONFLICT+'?action=run&run_id='+encodeURIComponent(id));S.run=j.run;renderValidation()}catch(e){toast(e.message,'error')}}
async function completeValidation(){const b=$('completeValidation');b.disabled=true;try{await request(CONFLICT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'complete',run_id:S.run.run_id})});const j=await syncRun();S.batch=j.batch;await loadRun(S.run.run_id);renderFinal();unlock(6);toast(j.message,'success')}catch(e){toast(e.message,'error')}finally{b.disabled=false}}
function renderLifecycle(status){const stages=['Draft','Validated','Ready to Publish','Published'],idx=stages.indexOf(status);return stages.map((x,i)=>`<span class="cln-life ${i<idx?'done':i===idx?'current':''}"><i class="ti ti-${i<idx?'circle-check-filled':i===idx?'circle-dot-filled':'circle'}"></i>${x}</span>${i<stages.length-1?'<i class="ti ti-chevron-right text-muted"></i>':''}`).join('')}
function renderFinal(){const b=S.batch;if(!b)return;$('finalName').innerHTML=`<i class="ti ti-calendar-check me-1"></i>${esc(b.schedule_name)}`;$('finalMeta').textContent=`${b.reference_no} · ${b.target_academic_year} · ${b.target_semester} · ${b.program} / ${b.target_code}`;$('lifecycle').innerHTML=renderLifecycle(b.status);$('finalBanner').innerHTML=b.status==='Published'?'<div class="cln-success"><i class="ti ti-check"></i><div><b>Schedule published successfully</b><div>The validated clone is now part of the published class schedule.</div></div></div>':b.status==='Ready to Publish'?'<div class="cln-success"><i class="ti ti-shield-check"></i><div><b>Validated and Ready to Publish</b><div>The completed Conflict Checker result is linked to this clone.</div></div></div>':`<div class="alert alert-warning"><i class="ti ti-alert-triangle me-1"></i>Status: ${esc(b.status)}. Recheck validation before publishing.</div>`;$('finalRows').innerHTML=b.entries.map(e=>`<tr><td><b>${esc(e.subject_code)}</b><small class="d-block text-muted">${esc(e.subject_name)}</small></td><td>${esc(e.teacher_name||'Unassigned')}</td><td>${esc(e.room_code||'Unassigned')}</td><td>${esc(e.day_of_week||'Unassigned')}<small class="d-block text-muted">${esc(e.start_time||'')} – ${esc(e.end_time||'')}</small></td><td>${esc(e.class_type)}</td><td>${pill(e.status)}</td></tr>`).join('');$('editEntries').href=`${BASE}/modules/scheduling/pages/teacher-schedule-mapping.php?section_code=${encodeURIComponent(b.target_code)}`;$('publishClone').disabled=b.status!=='Ready to Publish';$('publishClone').classList.toggle('d-none',b.status==='Published')}
async function refreshBatch(){if(!S.batch)return;try{const j=await request(API+'?action=batch&id='+S.batch.id);S.batch=j.batch;S.run=null;if(S.step===5)renderValidation();else renderFinal();toast('The latest saved Draft and validation status are loaded.','success')}catch(e){toast(e.message,'error')}}
async function publishClone(){if(!confirm('Publish this validated cloned schedule? This makes it visible as the official class schedule.'))return;const b=$('publishClone');b.disabled=true;try{const j=await request(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'publish',batch_id:S.batch.id})});S.batch=j.batch;renderFinal();toast(j.message,'success')}catch(e){toast(e.message,'error')}finally{b.disabled=false}}
function exportCsv(){if(!S.batch)return;const lines=[['Reference','Subject','Faculty','Room','Day','Start','End','Type','Status'],...S.batch.entries.map(e=>[S.batch.reference_no,e.subject_code,e.teacher_name,e.room_code,e.day_of_week,e.start_time,e.end_time,e.class_type,e.status])];const csv=lines.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${S.batch.reference_no}-cloned-schedule.csv`;a.click();URL.revokeObjectURL(a.href)}
function renderHistory(){const rows=S.data?.history||[];$('historyBody').innerHTML=rows.length?`<div class="table-responsive"><table class="table cln-table"><thead><tr><th>Reference</th><th>Source → Target</th><th>Target Term</th><th>Entries</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.reference_no)}</b><small class="d-block text-muted">${esc(x.schedule_name)}</small></td><td>${esc(x.source_code)} → ${esc(x.target_code)}</td><td>${esc(x.target_academic_year)}<small class="d-block text-muted">${esc(x.target_semester)}</small></td><td>${x.cloned_count}</td><td>${pill(x.status)}</td><td>${esc(x.created_at)}</td><td><button class="btn btn-sm btn-outline-primary" data-view-batch="${x.id}"><i class="ti ti-eye"></i></button></td></tr>`).join('')}</tbody></table></div>`:'<div class="cln-empty"><i class="ti ti-history-off"></i><br>No cloning history yet.</div>';$('historyBody').querySelectorAll('[data-view-batch]').forEach(x=>x.onclick=()=>showBatch(+x.dataset.viewBatch))}
async function showBatch(id){try{const j=await request(API+'?action=batch&id='+id),b=j.batch;$('historyBody').innerHTML=`<button class="btn btn-sm btn-outline-secondary mb-3" id="historyBack"><i class="ti ti-arrow-left me-1"></i>All History</button><h3 class="h5">${esc(b.reference_no)} · ${esc(b.schedule_name)}</h3><p>${pill(b.status)} ${esc(b.source_code)} (${esc(b.source_academic_year)}) → ${esc(b.target_code)} (${esc(b.target_academic_year)})</p><div class="table-responsive"><table class="table cln-table"><thead><tr><th>When</th><th>Action</th><th>Status Change</th><th>Detail</th><th>User</th></tr></thead><tbody>${b.history.map(h=>`<tr><td>${esc(h.changed_at)}</td><td>${esc(h.action)}</td><td>${esc(h.from_status||'—')} → ${esc(h.to_status||'—')}</td><td>${esc(h.detail)}</td><td>${esc(h.changed_by_name)}</td></tr>`).join('')}</tbody></table></div>`;$('historyBack').onclick=renderHistory}catch(e){toast(e.message,'error')}}
document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>go(+b.dataset.back));document.querySelectorAll('.cln-step').forEach(b=>b.onclick=()=>go(+b.dataset.step));$('applySourceFilters').onclick=renderSources;$('sourceSearch').oninput=renderSources;$('resetSource').onclick=()=>{['sourceAY','sourceSem','sourceProgram','sourceSearch'].forEach(id=>$(id).value='');S.source=null;$('selectedSource').classList.add('d-none');$('toConfigure').disabled=true;renderSources()};$('toConfigure').onclick=()=>unlock(2);['targetAY','targetSem','targetProgram'].forEach(id=>$(id).onchange=populateTargets);$('targetSection').onchange=targetChanged;$('scheduleName').oninput=()=>$('scheduleName').dataset.edited='1';$('applyShift').onchange=()=>{$('shiftMinutes').disabled=!$('applyShift').checked};$('generatePreview').onclick=generatePreview;$('reviewClone').onclick=()=>{renderConfirm();unlock(4)};$('createDraft').onclick=createDraft;$('recheckClone').onclick=()=>runConflict(true);$('completeValidation').onclick=completeValidation;$('reviewDraft').onclick=()=>go(5);$('saveDraftState').onclick=refreshBatch;$('publishClone').onclick=publishClone;$('exportClone').onclick=exportCsv;$('printClone').onclick=()=>print();$('clnPrint').onclick=()=>print();$('clnHistory').onclick=()=>{$('clnOverlay').classList.remove('d-none');renderHistory()};$('closeHistory').onclick=()=>$('clnOverlay').classList.add('d-none');$('clnOverlay').onclick=e=>{if(e.target===$('clnOverlay'))$('clnOverlay').classList.add('d-none')};load();
})();
</script>
<?php require_once __DIR__ . '/../../../includes/layout-end.php'; ?>
